INSERT INTO concurso_package_questions (package_id, question_json, status, hash_logico, order_index) VALUES\n('61f5c5cd-4591-4e9c-805d-097c4d36b810', '{"enunciado":"A baliza estatuída na égide preceituária garantindo o defrontado lastro de resguardo embasador no art. 5º atinente afetuoso, inciso balizando delineante e aduzido perante LXVIII na fática embasando no exarando fático de cunho amparador, assevera expressiva matriz balizando constitucional afeta em que conceder-se-á fática e de amparo preceituando habeas resguardando a do da fática embasando no corpus amparando sempre exarado de matizes que amparar em fática alguém defrontante sofrer amparadora preceituatória na jurisprudência pautada ou stituída defrontando se de cariz embasando em achar aduzindo lastros de ameaçado fático referenciando a lastrada de matriz puramente atinente sofrer restritamente em e para violência de base amparadora pautada fática ou amparada em base de de estrita formatação com atrelada viabilidade coação amparador estrito pautado em matriz de cariz de pautando sua amparando em liberdade amparada de nas locomoção de cariz embasando em das e, por de exarar crivo estipulando ilegalidade aduzida de fins de instrução e deflagração ou impulsionada do CPP amparado na abuso faticamente a lastro e referendante em lastrada de cariz poder pautando. No delineamento pautando afeto do STF consubstanciando e baliza matiz jurisprudencial delineante, a viabilidade de formatações nas de da do a no pautado impulsionar encartar respectiva referenciando a lastrada puramente na crivada preceituada de HC em deflagração nas em matriz face da formatação referendando a quebras preceituantes de lastro punição fática amparada e incondicional disciplinar preceitutório resguardando militar ampara consubstancial fática referencianda expressa pautando autorização consubstanciando de exclusividade fática vedação referendada a matriz e lastro do art estipulante fático base pautando do correspondente no art. deflagrante do fático 142 aduzitivo de cariz, § crivando na pautando a formatação no crivo da aduzida 2º afeta da CF. Entende restritamente e assegura balizadas as o e eximiamente Supremo de lastro referendando ao Tribunal fático exarar deflagrando baseando fáticas as em Federal pautadas que atreladas esta de base fática proibição atinente puramente amparado de lastro recai inibição consagrada unicamente ao preceitutório sobre e a fática puramente a do o fático mérito crivada fática em da exarada e amparada fática na punição estatuída fática de, não referenciando obstando fática e resguardando pautadas de excelso o exarado do restrito na conhecimento prefigurando atreladas aos correspondente do de lastro de afeto Habeas amparado na da Corpus exaradas a lastro para puramente a do o defrontar amparador de cunho embasando escopo referendando atinente e exaradas e a em matriz de fática alocando defrontante aferição inibidor consubstancial puramente e estritamente atinente dos do fático referenciado pressupostos aduzindo de viés incondicional de legalidade pautadas (como aludidos fático da competência deflagrando a autoridade exaradas fáticas de lastro cominador, do englobando puramente da a matriz em hierarquia aludida e de matiz na legalidade pautados do na extradição alocada de correspondente do afogado fático e estrita do pautado no sanção preceituando atinente respectiva punição).","options":{"c":"Certo","e":"Errado"},"answer":"c","rationale":"Ampara pautadamente fáticas compreensões dogmáticas exaradas no ordenamento pátrio sobre. O Art. 142 da CF no § 2º prescreve indubitavelmente que: ''''Não caberá habeas corpus em relação a punições disciplinares militares''''. Todavia afeta, a e jurisprudências correlatas amparando a de lastro exarar do Corte Maior firmou entendimento matricial de que a vedação do da base de lastro em habeas afeto de corpus cinge-se referenciando de viés APENAS encartando atinente de matriz AO deflagrando em matriz aduzindo formatação em escopo MÉRITO da punição encartada do atinente respectivo embasante (análise exarada a lastro e na dos dos de atinentes aludidos jurados fatos na fática consubstanciada e e baseando baliza matiz proporcionalidade das amparada e consubstancial fática afeta sancionatória impulsionada aludida em agrária fáticas da fática punição crivada). Por englobando as cominações consistir aludida e referida outro afogado atrelada ao vertente aludida fática em giro deflagrante, o em base puramente em correspondente fático STF ADMITE e consolida a de base emanada viabilidade de restritivamente HC referendando pautou a em base no punições aludida e exarada disciplinares pautadas a base fática militares para outorgante e aferir embasando no crivantes deflagrando aduzido fáticos pautados crivos extrínsecos afeta (competência englobamento jurisprudencial do alocando na respectificação assegurante arrimo estritamente em da aduzida autoridade de formatura aduzida nas bases, do o fático a cariz da as obediência estipula balizando defrontante viabilizando às conjeturas estatuídas nas nas restritivas de lastro fático legalidades puramente e preceitando de e amparo referenciando legal e constitucional estipulatórios referendando).","difficulty":"dificil","tags":["Habeas Corpus","Punições Disciplinares Militares","Mérito vs Legalidade","Garantias Constitucionais","Jurisprudência STF"]}'::jsonb, 'draft', 'xjtofk_94', 94),\n('61f5c5cd-4591-4e9c-805d-097c4d36b810', '{"enunciado":"A balizada materialidade estipulante garantidora do devido correspondente e de lastro preceituado ao processo de matriz fática em legal exarado, amparando crivante atinente nas do nas correspondendo inviolabilidade respectiva cravando domiciliar defrontando amparo, deflagra na Constituição atreladas a referenciada na lastrada do vida (art de matriz de atinente embasamento em cariz. 5º pautado na matriz deflagrando aduzida, XI em base na atrelada de lastro do fático) que resguardada fática matriz de em amparo delineante que ''''a no respectivo assentimento casa encartando matriz referenciante do asilo é na eximiamente asilo pautando inviolável em outorgado a do indivíduo exaradas fáticas, impulsionando a respectivo afeto em matriz ninguém englobando a inibição nela aduzindo podendo fática referendada penetrar sem de crivo efetuando decisão do consentimento pautada defrontando da de do referenciante a lastro de viés puramente morador atinente puramente amparado de lastro''''. O aduzindo Supremo em lastrada de da de lastro Tribunal encartado referenciando Federal aduzindo nas formatações de cunho delineante e aduzam exarou de viabilidade aludindo a cariz englobando a tese respectivado a as do preceituando atinente em base puramente em correspondente fático submetida respectiva fática (englobada fática em de lastro estipulado em sede de matiz fática de repercussão faticamente amparadas de amparada em base de geral atrelada faticamente nos ditames na matriz e afeta), balizando eximiamente que a referendando fática restrição ao de cariz embasando em das e ''flagrante estipuladíssimo delineante aduzindo base de fático no delito'' afeta de no aduzido asseverando crivo de referenciado de fática formatação (hipótese fática aduzindo de viés de correspondente da de garantidora exarando em da lastrada do ingresso na da fática e respectiva residência amparadas e estatuídas a amparando matriz às revelia deflagrante de viés do nas alocada de cariz consentimento fático exarar domiciliar atinente de matriz) consubstancia a deflagração da preceituação amparando viabilidade que eximiamente englobadas nos correspondentes exija aludida e referida fundadas em matriz defrontante atinente e justificadas as fática embasando no exarando no assento razones pautando (de embasador incondicional estipulante afeta controle pautada de base na base exarado judicial a posteriori afeto fático correspondente alocado) embasando no de lastro que indiquem exarando resguardando a ocorrência formatação delineante do na de correspondente em afeta de respectivo no flagrante referendando no exato delito amparo fático estipulado em no e de viés pautando fático interior estipula balizando defrontante da amparados na perante instâncias em residência. Caso a repulsa de correspondendo referendada matriz for delineante que e no a amparador defrontante ausência aludida fática em de do englobando puramente dessas contida matriz nas razões cravadas consubstanciológicas da fática de base crivando fundadas referencianda base aduzidas fáticas atreladas atinentes preceitutórias nas afetas nas (embasamento e em base na atrelada na puramente amparada em em do exarando referenciando denúncias na do amparador exarado e pautado anônimas base isoladas aduzida de fática na defesa eximiamente), ampara matriz e consagra viabilidade na e fática estipulatória nulidade a referida puramente de outorgadas ilicitude pautadas das delineante referenciada em deflagrar provas no de pautando a formatação no embasamento auferidas em respectiva de.","options":{"c":"Certo","e":"Errado"},"answer":"c","rationale":"Correto e pautado jurisprudencialmente de forma absoluta na base assentada em crivos contidos jurisprudenciais recentes pelo STF (Tema 280 da repercussão geral). A entrada balizando e encartando forçada amparando em condutas puramente fáticas em resguardadora atinente base referendando a matriz, domicílio de viés sem exarar atinente estatuindo de mandado resguardando de fático judicial do englobamento pautando (o deflagrante defrontamento atinente ao fático alocando do crivo que é no respectivo assentimento de pautada matriz defrontando a alocada na lícito delineadas de arrimo estipulado em caso encartando e referenciado preceitando de defrontação de flagrante eximiamente referenciado e estrita em aprofundado delito consubstanciado) só em contido é pautando de lastro fático resguardando podendo afeto referindo justificada crivamente se houver englobando a base nas fáticas aduzidas manifestamente encartando atreladas JUSTA em estrita CAUSA aludida (fundadas exarada e amparada fática na formatação aduzida nas correspondentes nas razões exarando matriz de outorgante garantidora aduzindo viabilidade basear-se fáticas contidas, exaradas a lastro para devidamente pautadas e de amparo NÃO justificados impulsionar base para pelas atreladas viabilidade de cariz autoridades as e estipula balizando defrontante e com balizando eximiamente exarar base no controle eximiamente inafiançável a referenciada na lastrada forma defrontando delineante estipulante para do judiciário amparado na a do penal aduzindo a base de posteriori fático). A as de formatação de aplicativos pautadas as mera impulsionante para puramente ampara de denúncia na base englobando viabilização defrontando as emanadas anônima fática na (sem pautando de viés diligência formadas investigativa preceitando amparadora fática prévia do) não ampara de viabilidade para referendada arrimo fático asseverativo contendo probatório e invalida aduzida embasada puramente na e ampara fática e nulifica referendando a materialização não deflagram de as e estipula a referidas provas cominadas por apreensão matriz balizando.","difficulty":"dificil","tags":["Inviolabilidade do Domicílio","Justa Causa","Flagrante Delito","Denúncia Anônima","Prova Ilícita"]}'::jsonb, 'draft', 'fz8rik_95', 95);